import React, { useState } from 'react';
import AuraCanvas from '../components/AuraCanvas';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score:1, emoji:'😔', label:'Väldigt dåligt', hues:[0,20],    intensity:0.7, speed:0.3  },
  { score:2, emoji:'😟', label:'Dåligt',         hues:[15,350],  intensity:0.65,speed:0.38 },
  { score:3, emoji:'😐', label:'Okej',           hues:[40,30],   intensity:0.55,speed:0.45 },
  { score:4, emoji:'🙂', label:'Bra',            hues:[155,175], intensity:0.6, speed:0.55 },
  { score:5, emoji:'😄', label:'Väldigt bra',    hues:[200,220], intensity:0.65,speed:0.7  },
];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [selected, setSelected] = useState(null);
  const [note,     setNote]     = useState('');
  const [step,     setStep]     = useState('pick');
  const activeM = selected !== null ? MOODS[selected] : MOODS[2];

  const save = () => { const m = MOODS[selected]; addMood(m.score, m.emoji, m.label, note); setStep('done'); };

  if (todayChecked && step !== 'done') return (
    <div style={{ position:'relative', height:'100vh', overflow:'hidden', background:'#0d0d0d' }}>
      <AuraCanvas hues={[200,220]} intensity={0.5} speed={0.3} />
      <div style={{ position:'absolute', inset:0, zIndex:10, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', textAlign:'center', padding:'0 32px' }}>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(240,237,230,0.35)', marginBottom:16 }}>Redan incheckad</p>
        <h2 style={{ fontSize:36, fontWeight:700, letterSpacing:'-0.04em', color:'#f0ede6', marginBottom:24 }}>Kom tillbaka imorgon</h2>
        <div style={{ display:'flex', gap:10 }}>
          <button onClick={()=>setPage('history')} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(240,237,230,0.9)', color:'#0d0d0d', fontSize:13, fontWeight:600, border:'none' }}>Historik</button>
          <button onClick={()=>setPage('home')} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(255,255,255,0.08)', border:'1px solid rgba(255,255,255,0.12)', color:'rgba(240,237,230,0.6)', fontSize:13 }}>Hem</button>
        </div>
      </div>
    </div>
  );

  if (step === 'done') return (
    <div style={{ position:'relative', height:'100vh', overflow:'hidden', background:'#0d0d0d' }}>
      <AuraCanvas hues={activeM.hues} intensity={activeM.intensity} speed={activeM.speed} />
      <div style={{ position:'absolute', inset:0, zIndex:10, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', textAlign:'center', padding:'0 32px' }}>
        <div style={{ fontSize:56, marginBottom:16 }}>{MOODS[selected].emoji}</div>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(240,237,230,0.35)', marginBottom:8 }}>Sparat</p>
        <h2 style={{ fontSize:'clamp(28px,7vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#f0ede6', marginBottom:32 }}>{MOODS[selected].label}</h2>
        <div style={{ display:'flex', gap:10 }}>
          <button onClick={()=>setPage('history')} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(240,237,230,0.9)', color:'#0d0d0d', fontSize:13, fontWeight:600, border:'none' }}>Historik</button>
          <button onClick={()=>setPage('home')} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(255,255,255,0.08)', border:'1px solid rgba(255,255,255,0.12)', color:'rgba(240,237,230,0.6)', fontSize:13 }}>Hem</button>
        </div>
      </div>
    </div>
  );

  if (step === 'note') return (
    <div style={{ position:'relative', height:'100vh', overflow:'hidden', background:'#0d0d0d' }}>
      <AuraCanvas hues={activeM.hues} intensity={activeM.intensity} speed={activeM.speed} />
      <div style={{ position:'absolute', inset:0, zIndex:10, display:'flex', flexDirection:'column', padding:'28px 22px', paddingBottom:100 }}>
        <div style={{ display:'flex', justifyContent:'space-between', marginBottom:40 }}>
          <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,237,230,0.35)' }}>Check-in</span>
          <button onClick={()=>setStep('pick')} style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(240,237,230,0.35)' }}>← Ändra</button>
        </div>
        <div style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', textAlign:'center' }}>
          <div style={{ fontSize:64, marginBottom:14 }}>{MOODS[selected].emoji}</div>
          <h2 style={{ fontSize:'clamp(28px,7vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#f0ede6', marginBottom:8 }}>{MOODS[selected].label}</h2>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(240,237,230,0.3)', letterSpacing:'0.1em', marginBottom:36 }}>Hur kändes det?</p>
          <div style={{ width:'100%', background:'rgba(20,20,20,0.85)', backdropFilter:'blur(24px)', borderRadius:22, padding:'16px 18px', border:'1px solid rgba(255,255,255,0.08)', marginBottom:14 }}>
            <textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={255}
              placeholder="Valfri notering om dagen..."
              style={{ width:'100%', background:'transparent', border:'none', color:'rgba(240,237,230,0.8)', fontSize:15, fontWeight:300, resize:'none', height:80, outline:'none', lineHeight:1.7 }} />
          </div>
          <button onClick={save} style={{ width:'100%', padding:'15px', borderRadius:100, background:'rgba(240,237,230,0.92)', color:'#0d0d0d', fontSize:14, fontWeight:700, border:'none', boxShadow:'0 8px 32px rgba(0,0,0,0.4)' }}>Spara →</button>
        </div>
      </div>
    </div>
  );

  // Pick screen — whole screen is the mood, tap to select
  return (
    <div style={{ position:'relative', height:'100vh', overflow:'hidden', background:'#0d0d0d' }}>
      {/* Aura shifts with active selection */}
      <AuraCanvas hues={activeM.hues} intensity={activeM.intensity} speed={activeM.speed} />

      <div style={{ position:'absolute', inset:0, zIndex:10, display:'flex', flexDirection:'column', padding:'28px 22px', paddingBottom:100 }}>
        <div style={{ display:'flex', justifyContent:'space-between', marginBottom:'auto' }}>
          <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,237,230,0.35)' }}>Hur mår du idag?</span>
        </div>

        {/* Mood selector — minimal list at bottom */}
        <div style={{ display:'flex', flexDirection:'column', gap:4, marginBottom:14 }}>
          {MOODS.slice().reverse().map((m, i) => {
            const idx = 4 - i;
            const isSel = selected === idx;
            return (
              <button key={m.score}
                onMouseEnter={() => setSelected(idx)}
                onClick={() => setSelected(idx)}
                style={{ display:'flex', alignItems:'center', gap:14, padding:'13px 18px', borderRadius:16, background:isSel?'rgba(255,255,255,0.12)':'rgba(255,255,255,0.04)', border:`1px solid ${isSel?'rgba(255,255,255,0.2)':'rgba(255,255,255,0.06)'}`, transition:'all .2s cubic-bezier(0.16,1,0.3,1)', backdropFilter:'blur(12px)' }}>
                <span style={{ fontSize:24 }}>{m.emoji}</span>
                <span style={{ fontSize:15, fontWeight:isSel?600:300, color:isSel?'rgba(240,237,230,0.95)':'rgba(240,237,230,0.5)', flex:1, textAlign:'left', transition:'all .2s' }}>{m.label}</span>
                {isSel && <span style={{ fontSize:12, color:'rgba(240,237,230,0.4)' }}>→</span>}
              </button>
            );
          })}
        </div>

        <button onClick={() => selected !== null && setStep('note')} disabled={selected === null}
          style={{ width:'100%', padding:'15px', borderRadius:100, background:selected!==null?'rgba(240,237,230,0.92)':'rgba(255,255,255,0.07)', color:selected!==null?'#0d0d0d':'rgba(240,237,230,0.25)', fontSize:14, fontWeight:700, border:'none', transition:'all .3s' }}>
          Fortsätt →
        </button>
      </div>
    </div>
  );
}
